package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextToken
 */
public class ReaderBasedJsonParser_nextToken_TriageGen2Test {

    private ReaderBasedJsonParser createParser(String json) throws IOException {
        StringReader reader = new StringReader(json);
        // Using the constructor with Reader
        // Note: In a real Jackson environment, we'd use JsonFactory to create this, 
        // but for direct unit testing of the parser logic:
        return new ReaderBasedJsonParser(
                IOContext.bootstrap(),
                0,
                reader,
                null,
                null,
                null,
                0,
                0,
                true
        );
    }

    @Test
    public void testNextToken_EndOfString() throws IOException {
        ReaderBasedJsonParser parser = createParser("");
        Assert.assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_SimpleValueTypes() throws IOException {
        // Test True
        ReaderBasedJsonParser parserTrue = createParser("true");
        Assert.assertEquals(JsonToken.VALUE_TRUE, parserTrue.nextToken());
        Assert.assertNull(parserTrue.nextToken());

        // Test False
        ReaderBasedJsonParser parserFalse = createParser("false");
        Assert.assertEquals(JsonToken.VALUE_FALSE, parserFalse.nextToken());
        Assert.assertNull(parserFalse.nextToken());

        // Test Null
        ReaderBasedJsonParser parserNull = createParser("null");
        Assert.assertEquals(JsonToken.VALUE_NULL, parserNull.nextToken());
        Assert.assertNull(parserNull.nextToken());
    }

    @Test
    public void testNextToken_Numbers() throws IOException {
        // Positive number
        ReaderBasedJsonParser parserPos = createParser("123");
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parserPos.nextToken());

        // Negative number
        ReaderBasedJsonParser parserNeg = createParser("-123");
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parserNeg.nextToken());

        // Zero
        ReaderBasedJsonParser parserZero = createParser("0");
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parserZero.nextToken());
    }

    @Test
    public void testNextToken_Strings() throws IOException {
        ReaderBasedJsonParser parser = createParser("\"hello\"");
        Assert.assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        Assert.assertEquals("hello", parser.getText());
    }

    @Test
    public void testNextToken_Arrays() throws IOException {
        // Start and End Array
        ReaderBasedJsonParser parser = createParser("[]");
        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        Assert.assertNull(parser.nextToken());

        // Array with value
        ReaderBasedJsonParser parserVal = createParser("[1]");
        Assert.assertEquals(JsonToken.START_ARRAY, parserVal.nextToken());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parserVal.nextToken());
        Assert.assertEquals(JsonToken.END_ARRAY, parserVal.nextToken());
    }

    @Test
    public void testNextToken_Objects() throws IOException {
        // Start, Field, Value, End Object
        ReaderBasedJsonParser parser = createParser("{\"key\":\"val\"}");
        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        Assert.assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        Assert.assertEquals("key", parser.getCurrentName());
        Assert.assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        Assert.assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        Assert.assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_FieldThenValue() throws IOException {
        // Tests the _nextAfterName() branch logic
        ReaderBasedJsonParser parser = createParser("{\"a\":1}");
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        // The logic in nextToken() says if current is FIELD_NAME, it calls _nextAfterName
        // which should return the value token immediately.
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextToken_MismatchedEndArray() throws IOException {
        // Test error: } in non-object context
        ReaderBasedJsonParser parser = createParser("}");
        try {
            parser.nextToken();
            Assert.fail("Should have thrown MismatchedInputException");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextToken_MismatchedEndObject() throws IOException {
        // Test error: ] in non-array context
        ReaderBasedJsonParser parser = createParser("]");
        try {
            parser.nextToken();
            Assert.fail("Should have thrown MismatchedInputException");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextToken_UnexpectedChar() throws IOException {
        // Test error: ] or } when expecting value
        ReaderBasedJsonParser parser = createParser("[ ] ]");
        parser.nextToken(); // [
        parser.nextToken(); // ]
        try {
            parser.nextToken(); // This should hit the default case or error case for unexpected char
            Assert.fail("Should have thrown IOException due to unexpected char");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextToken_IncompleteToken() throws IOException {
        // This tests the _tokenIncomplete branch
        // We simulate this by providing a string that might be considered partial if the parser were in a specific state
        // Since we can't easily force _tokenIncomplete without reflection, we test a standard string.
        ReaderBasedJsonParser parser = createParser("\"test\"");
        Assert.assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextToken_ComplexNesting() throws IOException {
        String json = "{\"a\":[1,2,{\"b\":true}],\"c\":null}";
        ReaderBasedJsonParser parser = createParser(json);

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        Assert.assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        Assert.assertEquals("a", parser.getCurrentName());

        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        Assert.assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        Assert.assertEquals("b", parser.getCurrentName());
        Assert.assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());
        Assert.assertEquals(JsonToken.END_OBJECT, parser.nextToken());

        Assert.assertEquals(JsonToken.END_ARRAY, parser.nextToken());

        Assert.assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        Assert.assertEquals("c", parser.getCurrentName());
        Assert.assertEquals(JsonToken.VALUE_NULL, parser.nextToken());

        Assert.assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        Assert.assertNull(parser.nextToken());
    }
}
